def get_level(grade):
    if 1 <= grade <= 6:
        return "elementary"
    elif 7 <= grade <= 9:
        return "lower_secondary"
    else:
        return "upper_secondary"

def build_plan_object(grade, course_id, course_name, chapter_name, lesson_title, general_obj, cognitive_objs, affective_obj, motor_obj, method, tools, homework, week=1):
    level_id = get_level(grade)
    title = f"طرح درس {course_name}: {lesson_title} ({chapter_name})"
    
    cog_text = " • " + "\n • ".join(cognitive_objs)
    objectives = (
        f"هدف کلی:\n{general_obj}\n\n"
        f"اهداف رفتاری (حیطه شناختی):\n{cog_text}\n\n"
        f"اهداف حیطه عاطفی و نگرشی:\n • {affective_obj}\n\n"
        f"اهداف حیطه مهارتی و عملکردی:\n • {motor_obj}"
    )
    
    assessment = (
        f"ارزشیابی ورودی (تشخیصی): سنجش پیش‌نیازهای درسی و مهارت‌های ورودی مرتبط با {lesson_title}.\n"
        f"ارزشیابی تکوینی (فرآیندی): مشاهده دقیق فعالیت گروه‌ها، بررسی پاسخ پرسش‌های کلاسی و بازخورد کلامی فوری.\n"
        f"ارزشیابی پایانی (تراکمی): پرسش شفاهی از خلاصه مبحث و تکمیل کاربرگ ارزشیابی پایانی.\n"
        f"تکلیف و فعالیت‌های خارج از کلاس: {homework}"
    )
    
    now = 1732348800000
    return {
        "id": f"lp-g{grade}-{course_id}-{str(uuid.uuid4())[:8]}",
        "title": title,
        "teacherId": "",
        "courseId": course_id,
        "grade": grade,
        "levelId": level_id,
        "sessionDate": "",
        "weekNumber": week,
        "chapter": chapter_name,
        "lessonName": lesson_title,
        "objectives": objectives,
        "teachingMethod": method,
        "resources": f"کتاب درسی {course_name} پایه {to_fa(grade)}، {tools}، کاربرگ یادگیری، تخته کلاسی/هوشمند",
        "assessment": assessment,
        "blocks": make_blocks(course_name, lesson_title, method),
        "status": "draft",
        "history": [],
        "createdAt": now,
        "updatedAt": now
    }

